package com.csust.eyediagnosis.workflow.evidence;
import com.csust.eyediagnosis.workflow.domain.SafetyAbstentionReasonCode; import org.junit.jupiter.api.Test; import java.util.List; import java.util.concurrent.atomic.AtomicInteger; import static org.junit.jupiter.api.Assertions.*;
class EvidenceRetrievalActionTest { @Test void safetyAbstentionCannotCallRetrieverOrRevealAQuery() { AtomicInteger calls = new AtomicInteger(); EvidenceRetrievalAction action = new EvidenceRetrievalAction(query -> { calls.incrementAndGet(); return List.of(); }, new FixedEvidenceTermCatalog()); EvidenceRetrievalBatch batch = action.execute(EvidenceFixtures.abstention(SafetyAbstentionReasonCode.OOD), EvidenceFixtures.exposure(EvidenceFixtures.abstention(SafetyAbstentionReasonCode.OOD))); assertTrue(batch.skipped()); assertEquals(0, calls.get()); } }
